// Three columns holding one sprint's tasks. Every task is a card and every card is a task;
// events never appear.
//
// A sprint is a date range, not a stored field, so moving a card to another sprint is exactly a
// change of its start and end - and a repeating task contributes one card per occurrence inside
// the sprint, each moved by an override of its own.
import { STAGES, sprintRange, byImportance, patchOccurrence } from './data.js';
import { S, el, phone, colorOf, iconBtn, dayLabel, STAGE_COLOR } from './ui.js';
import { collect } from './views.js';
import { openNew } from './popup.js';

export function renderKanban(host) {
  const range = sprintRange(S.view.sprint, S.model.settings);
  const tasks = collect(range.start, range.end).filter(o => o.type === 'task' && passes(o));

  const board = el('div', 'kb');
  board.style.setProperty('--col', String(S.view.col));
  for (const stage of STAGES) {
    const cards = tasks.filter(o => o.stage === stage).sort(byImportance);
    const col = el('div', 'kcol');
    col.dataset.stage = stage;
    const head = columnHead(stage, range.start);
    const body = el('div', 'kcards');
    if (!cards.length) body.append(el('p', 'day-empty', 'Nothing here.'));
    for (const o of cards) body.append(card(o));
    col.append(head, body);
    board.append(col);
  }

  host.className = `view vK${phone() ? ' one' : ''}`;
  host.replaceChildren(board);
  wire(board);
}

// A column header carries its state, in that state's colour, and a `+` that creates a task in
// that stage - the pane has no `+`, so this is the board's only way to make one. There is no
// colour dot and no card count: the dot said what the coloured name says, and a count is a
// number nobody acts on. On a phone the header is also how you page between the three columns.
function columnHead(stage, sprintStart) {
  const head = el('div', 'khead');
  const mid = el('div', 'kmid');

  // `‹` `›` flank the name and are drawn apart from the card buttons, which mean something
  // else entirely: they move a card. Disabled at either end rather than wrapping. On a desktop
  // every column is on screen, so there is nothing for them to page.
  if (phone()) mid.append(pager(-1));
  const name = el('span', 'kname', stage);
  name.style.color = STAGE_COLOR[stage];
  mid.append(name);
  if (phone()) mid.append(pager(1));

  const add = iconBtn('plus', `Add a task to ${stage}`, 'kadd');
  add.addEventListener('click', () =>
    openNew({ dayKey: sprintStart, type: 'task', stage, allDay: true }));
  // On a phone the pager fills the header, so the left track that balances the `+` is dropped.
  head.append(el('span', 'kpad'), mid, add);
  return head;
}

function pager(dir) {
  const b = iconBtn('chev', dir < 0 ? 'Previous column' : 'Next column',
    `knav${dir > 0 ? ' next' : ''}`);
  b.disabled = dir < 0 ? S.view.col === 0 : S.view.col === STAGES.length - 1;
  b.addEventListener('click', () => {
    S.view.col = Math.max(0, Math.min(STAGES.length - 1, S.view.col + dir));
    S.render();
  });
  return b;
}

// The group filter is applied by collect(); these two are the board's own.
function passes(o) {
  const f = S.kfilter;
  if (f.importantOnly && !o.important) return false;
  if (f.assignee && !o.participants.includes(f.assignee)) return false;
  return true;
}

function card(o) {
  const c = el('div', 'kcard');
  c.dataset.key = o.key;
  if (!phone()) c.draggable = true;       // on a phone the columns are paged from the header

  const bar = el('span', 'kbar');
  bar.style.background = colorOf(o.group);

  // A `!` in front of the title when the task is important, and the title. No pen - the card
  // opens on a click already - and no trashcan, which put the one irreversible action a thumb's
  // width from the title you were aiming at. The `!` is a marker, not a button: it is read here
  // and set in the entry popup's toggle row.
  const top = el('div', 'ktop');
  if (o.important) top.append(el('span', 'kbang', '!'));
  top.append(el('span', 'ktitle', o.title));

  // On a desktop the card is dragged between the columns, so a pair of arrows on every card is a
  // second way to do what the drag already does - in the one place it is also easiest to mistake
  // for the header's pager. On a phone there is nothing to drag onto, so the pair stays.
  if (phone()) {
    const back = iconBtn('chev', 'Previous stage', 'prev');
    const fwd = iconBtn('chev', 'Next stage', 'next');
    back.disabled = o.stage === 'todo';
    fwd.disabled = o.stage === 'done';
    back.addEventListener('click', () => shiftStage(o, -1));
    fwd.addEventListener('click', () => shiftStage(o, 1));
    top.append(back, fwd);
  }

  // That is the whole card: a coloured bar, a title and two lines. The estimate is edited in
  // the entry popup, and the sprint number was the same on every card, because a board shows
  // one sprint. There is no sprint control anywhere - a sprint is derived from the start date,
  // so moving a task to another one is changing its date.
  const main = el('div', 'kmain');
  main.append(top);
  if (o.body.trim()) main.append(el('p', 'kbody', o.body.trim()));
  main.append(el('p', 'kwhen', dayLabel(o.dayKey)));

  c.append(bar, main);
  return c;
}

// ---- moving a card -------------------------------------------------------------------------

const shiftStage = (o, dir) => {
  const next = STAGES[STAGES.indexOf(o.stage) + dir];
  if (next) patch(o, { stage: next }, `-> ${next}`);
};

// A card is deleted from the entry popup, not from the board: clicking the card opens it, its
// trashcan deletes the whole entry and its skip control drops a single occurrence.
const patch = (o, p, what) => act(`${o.title} ${what}`, () => patchOccurrence(o, p));

async function act(what, fn) {
  try {
    await fn();
  } catch (err) {
    return S.status(err.message, true);
  }
  S.model = await S.reload();
  S.render();
  S.push(`calendar: ${what}`);
}

// ---- dragging ------------------------------------------------------------------------------
// Desktop only. There is no swipe: on a phone one column fills the screen and the header's
// `<` `>` page between them, so a sideways gesture never has to be told apart from a drag.

function wire(board) {
  board.addEventListener('dragstart', e => {
    const c = e.target.closest('[data-key]');
    if (!c) return;
    e.dataTransfer.setData('text/plain', c.dataset.key);
    e.dataTransfer.effectAllowed = 'move';
  });
  board.addEventListener('dragover', e => { if (e.target.closest('.kcol')) e.preventDefault(); });
  board.addEventListener('drop', e => {
    const col = e.target.closest('.kcol');
    if (!col) return;
    e.preventDefault();
    const o = S.visible.get(e.dataTransfer.getData('text/plain'));
    if (o && o.stage !== col.dataset.stage) patch(o, { stage: col.dataset.stage }, `-> ${col.dataset.stage}`);
  });
}
===== settings.js =====
// The settings panel behind the gear.
//
// Everything here is stored on the device except the groups, the sprint length and the first
// sprint date: those three are data and live in the repo, because the sprint a task belongs to
// is derived from them and two devices that disagreed would put the same card in different
// sprints. Theme and date format are Mine-wide, not the calendar's.
//
// Every row is two halves - the label on the left, its control on the right - so the controls
// line up in one column. That alignment is the whole of what the panel was missing: a select, a
// text box, a checkbox and a date field each started wherever its own label happened to end.
// The groups are behind a button rather than listed, because a list grew with the repo and
// pushed the nine settings that never change below the fold.
import { setKV } from '../shared/store.js';
import { saveSettings, setZone, getZone } from './data.js';
import { THEMES, DATE_FORMATS, applyTheme, setPref } from '../shared/prefs.js';
import { openGroups } from './popup.js';
import { S, $, el, closePops } from './ui.js';

export function openSettings() {
  closePops();
  build();
  $('#settings-sheet').hidden = false;
  $('#scrim').hidden = false;
}

// Nine rows and nothing after them: there is no paragraph explaining what is stored where,
// because that belongs in REQUIREMENTS.md and not on a panel opened to change the theme.
function build() {
  $('#settings-body').replaceChildren(
    row('Groups', groupsButton()),
    row('Start week on', choose([[1, 'Monday'], [0, 'Sunday']], S.prefs.weekStart,
      v => local('weekStart', Number(v)))),
    row('Time zone', zoneField()),
    row('Date format', choose(DATE_FORMATS.map(f => [f, f]), S.prefs.dateFormat,
      v => mine('dateFormat', v))),
    row('Calendar weeks', toggle(S.prefs.showWeeks, v => local('showWeeks', v))),
    // The way back on. A prompt silenced from inside itself needs a row that can restore it,
    // because nothing in Mine may be switched off from a place that cannot switch it back on.
    row('Confirm discard', toggle(S.prefs.confirmDiscard, v => local('confirmDiscard', v))),
    row('Sprint length', numberField(S.model.settings.interval, 1,
      v => sprints({ interval: v })), 'weeks'),
    row('First sprint', dateField(S.model.settings.anchor, v => sprints({ anchor: v }))),
    row('Theme', choose(THEMES.map(t => [t, t]), S.prefs.theme, v => mine('theme', v)))
  );
}

// ---- rows ----------------------------------------------------------------------------------

// Two halves. A unit shares the right half with its control rather than dropping below it,
// which is the one place a row would otherwise go ragged again.
function row(label, control, suffix) {
  const r = el('div', 'srow');
  r.append(el('span', 'slab', label));
  if (!suffix) r.append(control);
  else {
    const v = el('div', 'sval');
    v.append(control, el('span', 'ssuf', suffix));
    r.append(v);
  }
  return r;
}

// The same popup the entry popup's category field opens, in its manage-only form: one place
// where a group is named or coloured, so there is no second list to keep in step.
function groupsButton() {
  const b = el('button', 'link', 'edit groups');
  b.type = 'button';
  b.id = 'edit-groups';
  b.addEventListener('click', openGroups);
  return b;
}

function choose(options, current, onChange) {
  const s = el('select');
  for (const [v, text] of options) {
    const o = el('option', '', text);
    o.value = String(v);
    if (String(v) === String(current)) o.selected = true;
    s.append(o);
  }
  s.addEventListener('change', () => onChange(s.value));
  return s;
}

function toggle(current, onChange) {
  const i = el('input');
  i.type = 'checkbox';
  i.checked = !!current;
  i.addEventListener('change', () => onChange(i.checked));
  return i;
}

function numberField(current, min, onChange) {
  const i = el('input');
  i.type = 'number';
  i.min = String(min);
  i.value = String(current);
  i.addEventListener('change', () => {
    const n = Number(i.value);
    if (Number.isInteger(n) && n >= min) onChange(n); else i.value = String(current);
  });
  return i;
}

function dateField(current, onChange) {
  const i = el('input');
  i.type = 'date';
  i.value = current;
  i.addEventListener('change', () => { if (i.value) onChange(i.value); });
  return i;
}

// A zone name, not an offset: a plain UTC+1 is an hour wrong for half the year in any zone with
// daylight saving. Empty means the device's own.
function zoneField() {
  const i = el('input');
  i.value = S.prefs.timeZone;
  i.placeholder = getZone();
  i.autocapitalize = 'off';
  i.spellcheck = false;
  i.addEventListener('change', () => {
    const typed = i.value.trim();
    const chosen = setZone(typed);
    if (typed && chosen !== typed) {
      i.value = '';
      S.status(`"${typed}" is not a zone name — using ${chosen}.`, true);
    }
    local('timeZone', i.value.trim());
    i.placeholder = getZone();
  });
  return i;
}

// ---- writes --------------------------------------------------------------------------------

async function sprints(patch) {
  await saveSettings({ ...S.model.settings, ...patch });
  S.model = await S.reload();
  build();
  S.render();
  S.push('calendar: sprint settings');
}

async function local(key, value) {
  S.prefs[key] = value;
  await setKV(`calendar.${key}`, value);
  S.render();
}

async function mine(key, value) {
  S.prefs[key] = value;
  await setPref(key, value);
  if (key === 'theme') applyTheme(value);
  S.render();
}

